#!/usr/bin/env node
// Builds the trikey.app blog from site/blog/posts/*.md, and the files that list every page. No dependencies.
//
//   node tools/site/build-blog.mjs                       write the generated files into site/
//   node tools/site/build-blog.mjs --check               exit 1 if site/ differs from what a build would write
//   node tools/site/build-blog.mjs --drafts --out DIR    preview: copy site/ to DIR and build it with drafts too
//
// It writes:
//   site/blog/<slug>.html   one page per published post (served at https://trikey.app/blog/<slug>)
//   site/blog/index.html    the list of posts, newest first
//   site/blog/feed.xml      RSS 2.0 feed of the posts
//   site/sitemap.xml        every indexable page: the top-level pages without noindex, the blog and its posts
//   site/index.html         only the FAQPage JSON-LD block, rebuilt from the page's own Questions section
//
// The post format is documented in site/README.md ("Blog").
import { cpSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { imageSize } from './image-size.mjs';
import { escapeHtml, markdownToHtml, wordCount } from './markdown.mjs';

export const SITE_URL = 'https://trikey.app';
export const SITE_DIR = resolve(dirname(fileURLToPath(import.meta.url)), '../../site');
export const GENERATED_MARKER = 'Generated by tools/site/build-blog.mjs';
const REPO = 'https://github.com/TheIcarusWings/trikey';
const CSP = "default-src 'self'; base-uri 'none'; form-action 'none'";
const DEFAULT_IMAGE = { path: '/img/share.png', width: 1200, height: 630, alt: 'The Trikey logo, a triangle of three dots, next to the words: A 2-of-3 multisig bitcoin wallet. No company holds a key.' };
const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const KNOWN_KEYS = new Set(['title', 'description', 'date', 'updated', 'slug', 'keywords', 'draft', 'image', 'image_alt']);
const WORDS_PER_MINUTE = 225;

export class BuildError extends Error {
  constructor(errors) {
    super(`The blog didn't build:\n${errors.map((e) => `  - ${e}`).join('\n')}`);
    this.errors = errors;
  }
}

// ---------------------------------------------------------------------------------------------------------------
// Front matter: the small subset of YAML the post format uses. One "key: value" per line; values are strings
// (bare, "double" or 'single' quoted), true/false, dates (YYYY-MM-DD) or [inline, lists]. "# comments" are ignored.

function parseScalar(raw, where) {
  const v = raw.trim();
  if (v.startsWith('"')) {
    const m = /^"((?:[^"\\]|\\.)*)"\s*(?:#.*)?$/.exec(v);
    if (!m) throw new Error(`${where}: unterminated "string"`);
    try {
      return JSON.parse(`"${m[1]}"`);
    } catch {
      throw new Error(`${where}: bad escape in "string"`);
    }
  }
  if (v.startsWith("'")) {
    const m = /^'((?:[^']|'')*)'\s*(?:#.*)?$/.exec(v);
    if (!m) throw new Error(`${where}: unterminated 'string'`);
    return m[1].replace(/''/g, "'");
  }
  const bare = v.replace(/\s+#.*$/, '').trim();
  if (bare === 'true') return true;
  if (bare === 'false') return false;
  if (bare === '' || bare === '~' || bare === 'null') return null;
  if (bare === '|' || bare === '>' || bare.startsWith('|') || bare.startsWith('>')) {
    throw new Error(`${where}: multi-line values aren't supported; put the value on one line, in quotes`);
  }
  return bare;
}

function splitList(inner, where) {
  const items = [];
  let cur = '';
  let quote = null;
  for (const c of inner) {
    if (quote) {
      cur += c;
      if (c === quote) quote = null;
    } else if (c === '"' || c === "'") {
      quote = c;
      cur += c;
    } else if (c === ',') {
      items.push(cur);
      cur = '';
    } else cur += c;
  }
  if (quote) throw new Error(`${where}: unterminated string in list`);
  if (cur.trim() !== '') items.push(cur);
  return items.map((s) => parseScalar(s, where)).filter((s) => s !== null && s !== '');
}

/** Splits a post into { data, body }. Throws with a readable message if the front matter is malformed. */
export function parseFrontMatter(text, file = 'post') {
  const src = String(text).replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n');
  if (!src.startsWith('---\n')) throw new Error(`${file}: must start with front matter between two "---" lines`);
  const end = src.indexOf('\n---', 3);
  if (end < 0 || !/^\n---[ \t]*(\n|$)/.test(src.slice(end))) throw new Error(`${file}: front matter has no closing "---" line`);
  const head = src.slice(4, end);
  const body = src.slice(end).replace(/^\n---[ \t]*\n?/, '');
  const data = {};
  head.split('\n').forEach((line, k) => {
    const where = `${file}, front matter line ${k + 2}`;
    if (line.trim() === '' || line.trim().startsWith('#')) return;
    const m = /^([A-Za-z_][\w-]*)[ \t]*:(.*)$/.exec(line);
    if (!m) throw new Error(`${where}: expected "key: value", got "${line}"`);
    if (Object.hasOwn(data, m[1])) throw new Error(`${where}: "${m[1]}" is set twice`);
    const raw = m[2].trim();
    if (raw.startsWith('[')) {
      const close = raw.lastIndexOf(']');
      if (close < 0 || raw.slice(close + 1).replace(/^\s*(#.*)?$/, '') !== '') throw new Error(`${where}: unterminated [list]`);
      data[m[1]] = splitList(raw.slice(1, close), where);
    } else data[m[1]] = parseScalar(raw, where);
  });
  return { data, body };
}

function isDate(s) {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const d = new Date(`${s}T00:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s;
}

/** Checks a post's front matter. Returns { post, errors, warnings }; post is null when there are errors. */
export function validatePost(data, file, fileSlug) {
  const errors = [];
  const warnings = [];
  const err = (m) => errors.push(`${file}: ${m}`);
  const warn = (m) => warnings.push(`${file}: ${m}`);

  for (const k of Object.keys(data)) if (!KNOWN_KEYS.has(k)) warn(`unknown front matter key "${k}" is ignored`);

  const title = typeof data.title === 'string' ? data.title.trim() : '';
  if (!title) err('"title" is required');
  else if (title.length > 90) warn(`title is ${title.length} characters; search results show about 60`);

  const description = typeof data.description === 'string' ? data.description.trim().replace(/\s+/g, ' ') : '';
  if (!description) err('"description" is required (the meta description, 120 to 160 characters)');
  else if (description.length < 50 || description.length > 200) err(`description is ${description.length} characters; it should be 120 to 160`);
  else if (description.length < 120 || description.length > 160) warn(`description is ${description.length} characters; 120 to 160 is best`);

  const date = data.date;
  if (!isDate(date)) err(`"date" is required, as YYYY-MM-DD (got ${JSON.stringify(date ?? null)})`);
  const updated = data.updated ?? null;
  if (updated !== null && !isDate(updated)) err(`"updated" must be a date, YYYY-MM-DD (got ${JSON.stringify(updated)})`);
  else if (updated !== null && isDate(date) && updated < date) err(`"updated" (${updated}) is before "date" (${date})`);

  const slug = data.slug ?? fileSlug;
  if (typeof slug !== 'string' || !SLUG.test(slug)) err(`"slug" must be lower-case words joined by hyphens (got ${JSON.stringify(slug)})`);
  else if (slug !== fileSlug) err(`"slug" is "${slug}" but the file is ${fileSlug}.md; they must match`);

  let keywords = data.keywords ?? [];
  if (typeof keywords === 'string') keywords = [keywords];
  if (!Array.isArray(keywords) || keywords.some((k) => typeof k !== 'string')) {
    err('"keywords" must be a list, like [multisig, self-custody]');
    keywords = [];
  }

  const draft = data.draft ?? false;
  if (typeof draft !== 'boolean') err(`"draft" must be true or false (got ${JSON.stringify(draft)})`);

  const image = data.image ?? null;
  if (image !== null && (typeof image !== 'string' || !image.startsWith('/'))) err('"image" must be a path on this site, like /blog/img/post.png');
  const imageAlt = typeof data.image_alt === 'string' ? data.image_alt.trim() : null;
  if (image && !imageAlt) err('"image" needs "image_alt", a description of the picture');

  if (errors.length) return { post: null, errors, warnings };
  return {
    post: {
      title,
      description,
      date,
      updated,
      slug,
      keywords: keywords.map((k) => k.trim()).filter(Boolean),
      draft,
      image,
      imageAlt,
    },
    errors,
    warnings,
  };
}

// ---------------------------------------------------------------------------------------------------------------
// Helpers

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

/** "2026-11-10" -> "10 November 2026" */
export function formatDate(iso) {
  const [y, m, d] = iso.split('-').map(Number);
  return `${d} ${MONTHS[m - 1]} ${y}`;
}

function rfc822(iso) {
  return new Date(`${iso}T00:00:00Z`).toUTCString();
}

/** JSON for a <script type="application/ld+json"> block: < > & are escaped so the text can't close the element. */
export function jsonLd(value) {
  return JSON.stringify(value, null, 2).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/&/g, '\\u0026');
}

function xmlEscape(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: '\u00a0', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“', hellip: '…', mdash: '—', ndash: '–', middot: '·', rarr: '→', larr: '←', darr: '↓' };

/** The text of an HTML fragment: tags dropped, entities decoded, whitespace collapsed. */
export function htmlText(html) {
  return String(html)
    .replace(/<[^>]*>/g, '')
    .replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (all, e) => {
      if (e[0] === '#') return String.fromCodePoint(e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10));
      return ENTITIES[e.toLowerCase()] ?? all;
    })
    .replace(/\s+/g, ' ')
    .trim();
}

/** The URL path a file in site/ is served at (Vercel cleanUrls: no .html, index.html is its directory). */
export function urlPathFor(rel) {
  const p = `/${rel.split('\\').join('/')}`;
  if (p.endsWith('/index.html')) return p.slice(0, -'index.html'.length).replace(/(.)\/$/, '$1');
  return p.replace(/\.html$/, '');
}

/** The file in site/ that serves a URL path, or null. Mirrors cleanUrls: /x is x.html or x/index.html. */
export function fileForPath(siteDir, urlPath) {
  const p = decodeURIComponent(urlPath.split('#')[0].split('?')[0]);
  const candidates = p.endsWith('/') ? [`${p}index.html`] : [p, `${p}.html`, `${p}/index.html`];
  for (const c of candidates) {
    const f = join(siteDir, c);
    if (!relative(siteDir, f).startsWith('..') && existsSync(f) && statSync(f).isFile()) return f;
  }
  return null;
}

