function layout(p) {
  const image = p.image ?? DEFAULT_IMAGE;
  const meta = [
    `<meta charset="utf-8">`,
    `<meta name="viewport" content="width=device-width, initial-scale=1">`,
    `<meta http-equiv="Content-Security-Policy" content="${CSP}">`,
    `<title>${escapeHtml(p.title)}</title>`,
    `<meta name="description" content="${escapeHtml(p.description)}">`,
  ];
  if (p.noindex) meta.push(`<meta name="robots" content="noindex">`);
  else meta.push(`<link rel="canonical" href="${escapeHtml(p.canonical)}">`);
  meta.push(
    `<meta property="og:type" content="${p.ogType}">`,
    `<meta property="og:site_name" content="Trikey">`,
    `<meta property="og:url" content="${escapeHtml(p.canonical)}">`,
    `<meta property="og:title" content="${escapeHtml(p.ogTitle ?? p.title)}">`,
    `<meta property="og:description" content="${escapeHtml(p.description)}">`,
    `<meta property="og:image" content="${escapeHtml(SITE_URL + image.path)}">`,
    `<meta property="og:image:width" content="${image.width}">`,
    `<meta property="og:image:height" content="${image.height}">`,
    `<meta property="og:image:alt" content="${escapeHtml(image.alt)}">`,
    `<meta property="og:locale" content="en_US">`,
    ...(p.extraMeta ?? []),
    `<meta name="twitter:card" content="summary_large_image">`,
    `<meta name="color-scheme" content="light dark">`,
    `<meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">`,
    `<meta name="theme-color" content="#09090b" media="(prefers-color-scheme: dark)">`,
    `<link rel="icon" href="/favicon.svg" type="image/svg+xml">`,
    `<link rel="apple-touch-icon" href="/apple-touch-icon.png">`,
    `<link rel="alternate" type="application/rss+xml" title="Trikey blog" href="/blog/feed.xml">`,
    `<link rel="preload" href="/fonts/geist-latin-wght-normal.woff2" as="font" type="font/woff2" crossorigin>`,
    `<link rel="stylesheet" href="/style.css">`,
    `<link rel="stylesheet" href="/blog/blog.css">`,
    `<script type="application/ld+json">\n${jsonLd(p.jsonLd)}\n</script>`,
  );
  return `<!doctype html>
<!-- ${GENERATED_MARKER} from ${p.source}. Don't edit this file: edit the source, then run node tools/site/build-blog.mjs. -->
<html lang="en">
<head>
${meta.join('\n')}
</head>
<body class="blog-page">
${header(p.current)}

<main id="main">
${p.main}
</main>

${footer()}
</body>
</html>
`;
}

const ORGANIZATION = {
  '@type': 'Organization',
  '@id': `${SITE_URL}/#organization`,
  name: 'Trikey',
  url: `${SITE_URL}/`,
  logo: { '@type': 'ImageObject', url: `${SITE_URL}/apple-touch-icon.png`, width: 180, height: 180 },
  sameAs: [REPO],
};

function readingMinutes(words) {
  return Math.max(1, Math.round(words / WORDS_PER_MINUTE));
}

function postMeta(post) {
  const updated =
    post.updated && post.updated !== post.date
      ? ` · Updated <time datetime="${post.updated}">${formatDate(post.updated)}</time>`
      : '';
  return `<time datetime="${post.date}">${formatDate(post.date)}</time>${updated} · ${post.minutes} min read`;
}

function postPage(post, related) {
  const url = `${SITE_URL}/blog/${post.slug}`;
  const image = post.image ? { path: post.image, width: post.imageSize.width, height: post.imageSize.height, alt: post.imageAlt } : DEFAULT_IMAGE;
  const modified = post.updated ?? post.date;
  const ld = {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'BlogPosting',
        '@id': `${url}#article`,
        headline: post.title,
        description: post.description,
        url,
        mainEntityOfPage: url,
        datePublished: post.date,
        dateModified: modified,
        inLanguage: 'en',
        image: `${SITE_URL}${image.path}`,
        ...(post.keywords.length ? { keywords: post.keywords.join(', ') } : {}),
        wordCount: post.words,
        author: { '@type': 'Organization', name: 'Trikey', url: `${SITE_URL}/` },
        publisher: ORGANIZATION,
        isPartOf: { '@type': 'Blog', '@id': `${SITE_URL}/blog#blog`, name: 'Trikey blog', url: `${SITE_URL}/blog` },
      },
      {
        '@type': 'BreadcrumbList',
        itemListElement: [
          { '@type': 'ListItem', position: 1, name: 'Trikey', item: `${SITE_URL}/` },
          { '@type': 'ListItem', position: 2, name: 'Blog', item: `${SITE_URL}/blog` },
          { '@type': 'ListItem', position: 3, name: post.title, item: url },
        ],
      },
    ],
  };
  const relatedHtml = related.length
    ? `
  <section class="related" aria-labelledby="related-h">
    <h2 id="related-h">Keep reading</h2>
    <ul class="post-list">
${related.map((r) => listItem(r, 'h3')).join('\n')}
    </ul>
  </section>`
    : '';
  const draft = post.draft ? `\n      <p class="draft-badge">Draft: not published</p>` : '';
  const main = `<div class="wrap wrap-text">
  <article class="post">
    <header class="post-head">
      <nav class="crumbs" aria-label="Breadcrumb"><ol><li><a href="/">Trikey</a></li><li><a href="/blog">Blog</a></li></ol></nav>${draft}
      <h1>${escapeHtml(post.title)}</h1>
      <p class="post-dek">${escapeHtml(post.description)}</p>
      <p class="post-meta">${postMeta(post)}</p>
    </header>
    <div class="prose">
${post.html}
    </div>
    <aside class="post-note" aria-label="About Trikey">
      <p><strong>Trikey is pre-alpha and not audited.</strong> Don't use it with real funds yet. It's an open source 2-of-3 bitcoin wallet: your phone, any hardware wallet and a guardian on your own home server, and no company holds a key.</p>
      <p class="post-note-links"><a href="/">How Trikey works</a> <a href="${REPO}/blob/main/docs/testers.md">Help test it</a> <a href="${REPO}">Source on GitHub</a></p>
    </aside>
  </article>${relatedHtml}
</div>`;
  return layout({
    title: `${post.title} | Trikey`,
    ogTitle: post.title,
    description: post.description,
    canonical: url,
    noindex: post.draft,
    ogType: 'article',
    image,
    extraMeta: [
      `<meta property="article:published_time" content="${post.date}">`,
      `<meta property="article:modified_time" content="${modified}">`,
    ],
    jsonLd: ld,
    main,
    current: 'blog',
    source: `blog/posts/${post.slug}.md`,
  });
}

function listItem(post, h) {
  return `      <li>
        <article>
          <p class="post-meta">${postMeta(post)}</p>
          <${h}><a href="/blog/${post.slug}">${escapeHtml(post.title)}</a>${post.draft ? ' <span class="draft-badge">Draft</span>' : ''}</${h}>
          <p>${escapeHtml(post.description)}</p>
        </article>
      </li>`;
}

const BLOG_TITLE = 'Trikey blog: bitcoin multisig and self-custody security';
const BLOG_DESCRIPTION =
  'Articles on bitcoin self-custody: how 2-of-3 multisig works, what to do when a key goes missing, and how Trikey is built to keep your coins safe.';

function blogIndex(posts) {
  const url = `${SITE_URL}/blog`;
  const list = posts.length
    ? `<ol class="post-list">\n${posts.map((p) => listItem(p, 'h2')).join('\n')}\n    </ol>`
    : `<p class="empty">No posts yet. Follow the project on <a href="${REPO}">GitHub</a>, or subscribe to the <a href="/blog/feed.xml">RSS feed</a>.</p>`;
  const main = `<div class="wrap wrap-text">
  <header class="blog-head">
    <p class="eyebrow">Blog</p>
    <h1>Bitcoin self-custody, explained</h1>
    <p class="lead">How 2-of-3 multisig works, what happens when a key goes missing, and how Trikey is built to keep your coins safe. In plain language.</p>
    <p class="blog-feed"><a href="/blog/feed.xml">RSS feed</a></p>
  </header>
  <section aria-label="Posts">
    ${list}
  </section>
</div>`;
  return layout({
    title: BLOG_TITLE,
    description: BLOG_DESCRIPTION,
    canonical: url,
    noindex: posts.length === 0 || posts.every((p) => p.draft),
    ogType: 'website',
    jsonLd: {
      '@context': 'https://schema.org',
      '@type': 'Blog',
      '@id': `${url}#blog`,
      name: 'Trikey blog',
      url,
      description: BLOG_DESCRIPTION,
      inLanguage: 'en',
      publisher: ORGANIZATION,
      blogPost: posts.map((p) => ({
        '@type': 'BlogPosting',
        headline: p.title,
        url: `${SITE_URL}/blog/${p.slug}`,
        datePublished: p.date,
        dateModified: p.updated ?? p.date,
      })),
    },
    main,
    current: 'blog',
    source: 'blog/posts/',
  });
}

function absolutize(html) {
  return html.replace(/ (href|src)="\/(?!\/)/g, ` $1="${SITE_URL}/`);
}

function feed(posts) {
  const newest = posts.map((p) => p.updated ?? p.date).sort().at(-1);
  const items = posts.map(
    (p) => `    <item>
      <title>${xmlEscape(p.title)}</title>
      <link>${SITE_URL}/blog/${p.slug}</link>
      <guid isPermaLink="true">${SITE_URL}/blog/${p.slug}</guid>
      <pubDate>${rfc822(p.date)}</pubDate>
      <description>${xmlEscape(p.description)}</description>
${p.keywords.map((k) => `      <category>${xmlEscape(k)}</category>\n`).join('')}      <content:encoded><![CDATA[${absolutize(p.html).replace(/]]>/g, ']]]]><![CDATA[>')}]]></content:encoded>
    </item>`,
  );
  return `<?xml version="1.0" encoding="utf-8"?>
<!-- ${GENERATED_MARKER}. -->
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom" xmlns:content="http://purl.org/rss/1.0/modules/content/">
  <channel>
    <title>Trikey blog</title>
    <link>${SITE_URL}/blog</link>
    <description>${xmlEscape(BLOG_DESCRIPTION)}</description>
    <language>en</language>
    <atom:link href="${SITE_URL}/blog/feed.xml" rel="self" type="application/rss+xml"/>
${newest ? `    <lastBuildDate>${rfc822(newest)}</lastBuildDate>\n` : ''}${items.join('\n')}${items.length ? '\n' : ''}  </channel>
</rss>
`;
}

/** Top-level pages that should be in search results: not noindex, not the 404 page. */
export function indexablePages(siteDir, overrides = new Map()) {
  return readdirSync(siteDir)
    .filter((f) => f.endsWith('.html') && f !== '404.html')
    .sort()
    .map((f) => ({ file: f, html: overrides.get(f) ?? readFileSync(join(siteDir, f), 'utf8') }))
    .filter(({ html }) => !isNoindex(html))
    .map(({ file, html }) => ({
      path: urlPathFor(file),
      lastmod: /<meta name="dcterms\.modified" content="(\d{4}-\d{2}-\d{2})">/.exec(html)?.[1] ?? null,
    }));
}

export function isNoindex(html) {
  return /<meta\s+name="robots"\s+content="[^"]*noindex/i.test(html);
}

function sitemap(entries) {
  const urls = entries.map(
    (e) => `  <url>\n    <loc>${xmlEscape(SITE_URL + (e.path === '/' ? '/' : e.path))}</loc>\n${e.lastmod ? `    <lastmod>${e.lastmod}</lastmod>\n` : ''}  </url>`,
  );
  return `<?xml version="1.0" encoding="UTF-8"?>
<!-- ${GENERATED_MARKER}: the top-level pages without noindex, the blog and its published posts. -->
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.join('\n')}
</urlset>
`;
}

const FAQ_BLOCK = /(<script type="application\/ld\+json" id="faq-jsonld">)[\s\S]*?(<\/script>)/;

/** Rebuilds the FAQPage JSON-LD in index.html from its own Questions section, so the two can't drift apart. */
export function withFaqJsonLd(html) {
  if (!FAQ_BLOCK.test(html)) return html;
  const start = html.indexOf('<section id="faq"');
  const end = html.indexOf('</section>', start);
  if (start < 0 || end < 0) throw new Error('index.html has a faq-jsonld block but no <section id="faq">');
  const questions = [...html.slice(start, end).matchAll(/<details[^>]*>\s*<summary>([\s\S]*?)<\/summary>([\s\S]*?)<\/details>/g)].map((m) => ({
    '@type': 'Question',
    name: htmlText(m[1]),
    acceptedAnswer: { '@type': 'Answer', text: htmlText(m[2]) },
  }));
  if (!questions.length) throw new Error('index.html: no <details><summary> questions in <section id="faq">');
  const block = jsonLd({ '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: questions });
  return html.replace(FAQ_BLOCK, (_, open, close) => `${open}\n${block}\n${close}`);
}

// ---------------------------------------------------------------------------------------------------------------
// Build

/**
 * Builds everything in memory. Returns { files: Map<path relative to site/, contents>, posts, warnings }.
 * Throws BuildError listing every problem found. With drafts: true, drafts are built too (marked noindex), for
 * previewing only.
 */
export function buildSite(siteDir = SITE_DIR, { drafts = false } = {}) {
  const errors = [];
  const warnings = [];
  const postsDir = join(siteDir, 'blog', 'posts');
  const sources = existsSync(postsDir)
    ? readdirSync(postsDir)
        .filter((f) => f.endsWith('.md'))
        .sort()
    : [];

  const all = [];
  for (const name of sources) {
    const file = `site/blog/posts/${name}`;
    let parsed;
    try {
      parsed = parseFrontMatter(readFileSync(join(postsDir, name), 'utf8'), file);
    } catch (e) {
      errors.push(e.message);
      continue;
    }
    const v = validatePost(parsed.data, file, name.replace(/\.md$/, ''));
    errors.push(...v.errors);
    warnings.push(...v.warnings);
    if (v.post) all.push({ ...v.post, body: parsed.body, file });
  }

  const posts = all
    .filter((p) => drafts || !p.draft)
    .sort((a, b) => (a.date === b.date ? a.slug.localeCompare(b.slug) : a.date < b.date ? 1 : -1));
  const slugs = new Set(posts.map((p) => p.slug));

  for (const post of posts) {
    const checkInternal = (href) => {
      if (href.startsWith('#')) return null;
      if (!href.startsWith('/')) return `${post.file}: link "${href}": link to this site with a path from the root, like /blog/some-post`;
      const path = href.split('#')[0].split('?')[0];
      const m = /^\/blog\/([^/]+)$/.exec(path);
      if (m && m[1] !== 'feed.xml' && !m[1].includes('.')) {
        if (slugs.has(m[1])) return null;
        const isDraft = all.some((p) => p.slug === m[1]);
        return `${post.file}: link "${href}" goes to ${isDraft ? 'a draft' : 'a post that doesn\'t exist'}`;
      }
      if (path === '/blog' || path === '/blog/') return null;
      return fileForPath(siteDir, path) ? null : `${post.file}: link "${href}" goes to a page that doesn't exist in site/`;
    };
    const image = (src) => {
      const f = fileForPath(siteDir, src);
      if (!f) return `${post.file}: image "${src}" isn't a file in site/`;
      const size = imageSize(f);
      return size ?? `${post.file}: can't read the size of image "${src}" (use PNG, JPEG, WebP, GIF or SVG)`;
    };
    const md = markdownToHtml(post.body, { minHeading: 2, checkInternal, image });
    errors.push(...md.errors.map((e) => (e.startsWith(post.file) ? e : `${post.file}: ${e}`)));
    post.html = md.html;
    post.headings = md.headings;
    post.words = wordCount(post.body);
    post.minutes = readingMinutes(post.words);
    if (post.words < 1) errors.push(`${post.file}: the post has no text`);
    if (post.image) {
      const r = image(post.image);
      if (typeof r === 'string') errors.push(r);
      else {
        post.imageSize = r;
        if (r.width < 1200) warnings.push(`${post.file}: "image" is ${r.width}px wide; link previews want 1200×630`);
      }
    }
  }
  if (errors.length) throw new BuildError(errors);

  const files = new Map();
  for (const post of posts) {
    const related = posts
      .filter((p) => p !== post)
      .map((p) => ({ p, score: p.keywords.filter((k) => post.keywords.includes(k)).length }))
      .sort((a, b) => b.score - a.score || (a.p.date === b.p.date ? a.p.slug.localeCompare(b.p.slug) : a.p.date < b.p.date ? 1 : -1))
      .slice(0, 3)
      .map((r) => r.p);
    files.set(`blog/${post.slug}.html`, postPage(post, related));
  }
  files.set('blog/index.html', blogIndex(posts));
  files.set('blog/feed.xml', feed(posts.filter((p) => !p.draft)));

  const overrides = new Map();
  const indexFile = join(siteDir, 'index.html');
  if (existsSync(indexFile)) {
    const home = readFileSync(indexFile, 'utf8');
    const rebuilt = withFaqJsonLd(home);
    files.set('index.html', rebuilt);
    overrides.set('index.html', rebuilt);
  }

  const published = posts.filter((p) => !p.draft);
  const entries = indexablePages(siteDir, overrides);
  if (published.length) {
    entries.push({ path: '/blog', lastmod: published.map((p) => p.updated ?? p.date).sort().at(-1) });
    for (const p of published) entries.push({ path: `/blog/${p.slug}`, lastmod: p.updated ?? p.date });
  }
  files.set('sitemap.xml', sitemap(entries));

  return { files, posts, warnings };
}

/** Generated files in site/blog/ that the current build no longer produces (a post was deleted or made a draft). */
export function staleFiles(siteDir, files) {
  const dir = join(siteDir, 'blog');
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((f) => f.endsWith('.html'))
    .map((f) => `blog/${f}`)
    .filter((rel) => !files.has(rel) && readFileSync(join(siteDir, rel), 'utf8').includes(GENERATED_MARKER));
}

/** Lists how site/ differs from a fresh build: [] when it's up to date. */
export function diffSite(siteDir, files) {
  const problems = [];
  for (const [rel, content] of files) {
    const f = join(siteDir, rel);
    if (!existsSync(f)) problems.push(`site/${rel} is missing`);
    else if (readFileSync(f, 'utf8') !== content) problems.push(`site/${rel} is out of date`);
  }
  for (const rel of staleFiles(siteDir, files)) problems.push(`site/${rel} is left over from a post that's gone or now a draft`);
  return problems;
}

export function writeSite(siteDir, files) {
  const written = [];
  for (const [rel, content] of files) {
    const f = join(siteDir, rel);
    if (existsSync(f) && readFileSync(f, 'utf8') === content) continue;
    mkdirSync(dirname(f), { recursive: true });
    writeFileSync(f, content);
    written.push(rel);
  }
  const removed = staleFiles(siteDir, files);
  for (const rel of removed) rmSync(join(siteDir, rel));
  return { written, removed };
}

function shown(path) {
  const rel = relative(process.cwd(), path);
  return rel === '' ? '.' : rel.startsWith('..') ? path : rel;
}

function main(argv) {
  const args = new Set(argv.filter((a) => a.startsWith('--')));
  const outAt = argv.indexOf('--out');
  const out = outAt >= 0 ? argv[outAt + 1] : null;
  for (const a of args) if (!['--check', '--drafts', '--out', '--help'].includes(a)) throw new Error(`unknown option ${a} (try --help)`);
  if (args.has('--help')) {
    process.stdout.write(readFileSync(fileURLToPath(import.meta.url), 'utf8').split('\n').slice(1, 7).join('\n').replace(/^\/\/ ?/gm, '') + '\n');
    return 0;
  }
  if (args.has('--drafts') && !out) throw new Error('--drafts only builds into a preview copy: add --out <dir>');
  if (out && args.has('--check')) throw new Error('--check and --out don\'t go together');

  let siteDir = SITE_DIR;
  if (out) {
    siteDir = resolve(out);
    if (!relative(SITE_DIR, siteDir).startsWith('..') || !relative(siteDir, SITE_DIR).startsWith('..')) {
      throw new Error('--out must be a directory outside site/ that does not contain it');
    }
    // Only ever replace a directory this script made, never one that happens to have the same name.
    const stamp = join(siteDir, '.blog-preview');
    if (existsSync(siteDir) && readdirSync(siteDir).length && !existsSync(stamp)) {
      throw new Error(`${out} exists and isn't a preview made by this script; pick an empty or new directory`);
    }
    rmSync(siteDir, { recursive: true, force: true });
    cpSync(SITE_DIR, siteDir, { recursive: true });
    writeFileSync(stamp, 'A preview copy of site/ made by tools/site/build-blog.mjs --out. Safe to delete.\n');
  }

  let result;
  try {
    result = buildSite(siteDir, { drafts: args.has('--drafts') });
  } catch (e) {
    if (e instanceof BuildError) {
      process.stderr.write(`${e.message}\n`);
      return 1;
    }
    throw e;
  }
  for (const w of result.warnings) process.stderr.write(`warning: ${w}\n`);

  if (args.has('--check')) {
    const problems = diffSite(siteDir, result.files);
    if (problems.length) {
      process.stderr.write(
        `The generated site files don't match the posts:\n${problems.map((p) => `  - ${p}`).join('\n')}\nRun: node tools/site/build-blog.mjs, and commit the result.\n`,
      );
      return 1;
    }
    process.stdout.write(`Blog up to date: ${result.posts.length} published post(s).\n`);
    return 0;
  }

  const { written, removed } = writeSite(siteDir, result.files);
  for (const rel of written) process.stdout.write(`wrote   ${shown(join(siteDir, rel))}\n`);
  for (const rel of removed) process.stdout.write(`removed ${shown(join(siteDir, rel))}\n`);
  const drafts = result.posts.filter((p) => p.draft).length;
  process.stdout.write(
    `${result.posts.length - drafts} published post(s)${drafts ? `, ${drafts} draft(s)` : ''}; ${written.length || 'no'} file(s) changed.\n`,
  );
  if (out) process.stdout.write(`Preview: npx serve ${shown(siteDir)} (it serves /blog/<slug> like Vercel does), then open /blog\n`);
  return 0;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    process.exitCode = main(process.argv.slice(2));
  } catch (e) {
    process.stderr.write(`${e.message}\n`);
    process.exitCode = 2;
  }
}
